/// Заголовок документа по адресу; неизвестный адрес — `None` (страница не найдена).
fn doc_title(doc: &str) -> Option<&'static str> {
    DOCS.iter().find(|(slug, _)| *slug == doc).map(|(_, title)| *title)
}

/// Оформление пункта списка: точка слева за пределами колонки, как в вайрфрейме.
#[component]
fn Bullets(items: &'static [Bullet]) -> impl IntoView {
    view! {
        <ul class="pl-[44px] md:pl-[45px] mb-6 leading-[1.3]">
            {items
                .iter()
                .map(|b| {
                    view! {
                        <li class="relative mb-[2px]">
                            <span class="absolute -left-[21px]">"·"</span>
                            {b.text}
                            {(!b.sub.is_empty())
                                .then(|| {
                                    view! {
                                        <ul class="pl-[48px] mt-[2px]">
                                            {b.sub
                                                .iter()
                                                .map(|s| {
                                                    view! {
                                                        <li class="relative mb-[2px]">
                                                            <span class="absolute -left-[21px]">"·"</span>
                                                            {*s}
                                                        </li>
                                                    }
                                                })
                                                .collect_view()}
                                        </ul>
                                    }
                                })}
                        </li>
                    }
                })
                .collect_view()}
        </ul>
    }
}

/// Страница документа: заголовок, дата, вступление, оглавление, разделы.
#[component]
fn LegalDoc(title: &'static str) -> impl IntoView {
    view! {
        <section class="px-3 md:px-6 pt-10 pb-10 md:pt-20 md:pb-20">
            <h1 class="text-[26px] md:text-[40px] font-medium uppercase leading-[1.1]">{title}</h1>
        </section>
        <section class="reveal px-3 md:px-6 pb-20 md:pb-[100px] text-[16px] md:text-[18px] leading-[1.2]">
            <div class="max-w-[1040px] mr-auto">
                <p class="mb-4"><b class="font-bold">"Дата вступления в силу:"</b>" [дд.мм.гггг]"</p>
                <p class="mb-6">{INTRO}</p>
                <ul class="pl-[44px] md:pl-[45px] mb-6 leading-[1.3]">
                    {CONTENTS
                        .iter()
                        .map(|t| view! { <li class="relative mb-[2px]"><span class="absolute -left-[21px]">"·"</span>{*t}</li> })
                        .collect_view()}
                </ul>
                <p class="mb-6">{OUTRO}</p>
                {SECTIONS
                    .iter()
                    .enumerate()
                    .map(|(i, s)| {
                        view! {
                            <div class="mt-12 first:mt-0">
                                <div class="flex">
                                    <span class="w-[44px] md:w-[43px] shrink-0 font-medium uppercase leading-[1.2]">{format!("{}.", i + 1)}</span>
                                    <h2 class="font-medium uppercase leading-[1.2]">{s.title}</h2>
                                </div>
                                <div class="mt-6">
                                    {s.paras.iter().map(|p| view! { <p class="mb-6">{*p}</p> }).collect_view()}
                                </div>
                                <Bullets items=s.bullets />
                            </div>
                        }
                    })
                    .collect_view()}
            </div>
        </section>
    }
}

/// `/legal/:doc`: один шаблон для трёх документов; неизвестный адрес — 404.
#[component]
pub fn LegalPage() -> impl IntoView {
    let params = use_params_map();
    let doc = move || params.with(|p| p.get("doc")).unwrap_or_default();
    let known = move || doc_title(&doc());

    // Код ответа 404 — только на сервере, при первой отрисовке
    #[cfg(feature = "ssr")]
    if known().is_none() {
        if let Some(res) = use_context::<leptos_axum::ResponseOptions>() {
            res.set_status(axum::http::StatusCode::NOT_FOUND);
        }
    }

    view! {
        <Title text=move || known().unwrap_or("Страница не найдена") />
        {move || match known() {
            Some(title) => view! { <LegalDoc title=title /> }.into_any(),
            None => view! {
                <section class="px-3 md:px-6 py-20 md:py-[100px] min-h-[50vh] flex flex-col items-start gap-6">
                    <h1 class="h3">"Страница не найдена"</h1>
                    <a href="/" class="btn">"На главную"</a>
                </section>
            }
                .into_any(),
        }}
    }
}
